  if (!main) return ''
  const ids = [...main.querySelectorAll('[data-id]')].map((e) => e.getAttribute('data-id') || '')
  const direct = ids.map((v) => v.match(/^(?:true|false)_(\d{8,15})@c\.us/)).find(Boolean)
  if (direct) return direct[1]
  const header = main.querySelector('header')
  const named = header && header.querySelector('span[dir="auto"]')
  const title = ((named || header || {}).innerText || '').split('\n')[0].trim()
  if (number.test(title)) return title.match(number)[0]

  const lid = (ids.map((v) => v.match(/^(?:true|false)_(\d+@lid)/)).find(Boolean) || [])[1]
